class _Kernel:
    """Lazy, fail-safe wrapper around the embedded WASM tactical kernel.

    Instantiated once (before the pipe loop). Any failure — ``wasmtime`` absent,
    the grader sandbox blocking module instantiation (gate G0 is unverified), a
    smoke-test mismatch — leaves ``ok == False`` and every caller transparently
    falls back to the byte-identical Python model. The kernel is never a
    correctness dependency, only acceleration."""

    def __init__(self) -> None:
        self.ok = False
        self._store = None
        self._score = None
        self._mem = None
        try:
            import wasmtime  # whitelisted; lazy so its absence just disables WASM
            binary = zlib.decompress(base64.b85decode(_KERNEL_B85))
            store = wasmtime.Store()
            module = wasmtime.Module(store.engine, binary)
            inst = wasmtime.Instance(store, module, [])
            ex = inst.exports(store)
            self._store, self._score, self._mem = store, ex["score_candidates"], ex["mem"]
            # smoke test: one call must agree with the Python model, else disable
            ours = [(30.0, 30.0, 2.0)]
            enemies = [(34.0, 30.0, 3.0)]
            dirs = [(1.0, 0.0), (-1.0, 0.0)]
            wv = self._evaluate(ours, enemies, dirs, 1.0, 0.0, HeuristicParams())
            pv = _kernel_eval_py(ours, enemies, dirs, 1.0, 0.0, HeuristicParams())
            if wv is None or any(abs(a - b) > 1e-6 for a, b in zip(wv, pv)):
                return
            self.ok = True
        except Exception:
            self.ok = False

    def _evaluate(self, ours, enemies, dirs, bux, buy, params):
        """Pack state into wasm memory, run the kernel, read back per-candidate
        values. Returns None on any failure (caller falls back to Python)."""
        try:
            no, ne, nd = len(ours), len(enemies), len(dirs)
            end = 128 + no * 24 + ne * 24 + nd * 16
            buf = bytearray(end)
            struct.pack_into("<iii", buf, 0, no, ne, nd)
            struct.pack_into("<9d", buf, 16, spec.EAT_SIZE_RATIO,
                             params.death_penalty, params.search_gain_w,
                             params.search_align_w, spec.SPLIT_REACH,
                             spec.SPLIT_MIN_MASS, spec.ARENA_SIZE, bux, buy)
            off = 128
            for (x, y, r) in ours:
                struct.pack_into("<3d", buf, off, x, y, r); off += 24
            for (x, y, r) in enemies:
                struct.pack_into("<3d", buf, off, x, y, r); off += 24
            for (ux, uy) in dirs:
                struct.pack_into("<2d", buf, off, ux, uy); off += 16
            self._mem.write(self._store, bytes(buf), 0)
            self._score(self._store)
            out = self._mem.read(self._store, 65536, 65536 + nd * 8)
            return list(struct.unpack("<%dd" % nd, out))
        except Exception:
            return None

    def evaluate(self, ours, enemies, dirs, bux, buy, params):
        """Kernel valuation with a transparent Python fallback."""
        if self.ok:
            vals = self._evaluate(ours, enemies, dirs, bux, buy, params)
            if vals is not None:
                return vals
        return _kernel_eval_py(ours, enemies, dirs, bux, buy, params)


def _kernel_eval_py(ours, enemies, dirs, bux, buy, params: HeuristicParams):
    """Byte-identical Python twin of the WAT ``score_candidates`` kernel: for
    each candidate heading, advance our blobs one frame and score them against
    the split-aware effective-kill-radius model. Same operations in the same
    order as the WASM so the two agree to 0 ULP; it is the reference the loader
    smoke-tests against and the fallback when WASM is unavailable."""
    ratio = spec.EAT_SIZE_RATIO
    death = params.death_penalty
    gainw = params.search_gain_w
    alignw = params.search_align_w
    sreach = spec.SPLIT_REACH
    smin = spec.SPLIT_MIN_MASS
    arena = spec.ARENA_SIZE
    vals = []
    for (ux, uy) in dirs:
        surv = lost = gained = 0.0
        for (ox, oy, orr) in ours:
            mi = orr * orr
            sp = _speed(orr)
            lo = orr
            hi = arena - orr
            nx = min(max(ox + ux * sp, lo), hi)
            ny = min(max(oy + uy * sp, lo), hi)
            dead = False
            for (ex, ey, er) in enemies:
                em = er * er
                ddx = nx - ex
                ddy = ny - ey
                d2 = ddx * ddx + ddy * ddy
                if em >= ratio * mi:
                    killr = er + _speed(er)
                    if em >= smin and em * 0.5 >= ratio * mi:
                        killr = max(killr, er + sreach)
                    if d2 <= killr * killr:
                        dead = True
                if mi >= ratio * em and d2 <= orr * orr:
                    gained += em
            if dead:
                lost += mi
            else:
                surv += mi
        vals.append(surv + gainw * gained - death * lost
                    + alignw * (ux * bux + uy * buy))
    return vals


def _heading_lethal(ours, enemies, ux, uy, params: HeuristicParams) -> bool:
    """True if a single heading would step one of our blobs into a next-frame
    eat (the effective-kill-radius test for one direction). Cheap gate so the
    floor keeps the desired heading when it is already safe."""
    ratio = spec.EAT_SIZE_RATIO
    arena = spec.ARENA_SIZE
    for (ox, oy, orr) in ours:
        mi = orr * orr
        sp = _speed(orr)
        lo, hi = orr, arena - orr
        nx = min(max(ox + ux * sp, lo), hi)
        ny = min(max(oy + uy * sp, lo), hi)
        for (ex, ey, er) in enemies:
            em = er * er
            if em < ratio * mi:
                continue
            killr = er + _speed(er)
            if em >= spec.SPLIT_MIN_MASS and em * 0.5 >= ratio * mi:
                killr = max(killr, er + spec.SPLIT_REACH)
            ddx, ddy = nx - ex, ny - ey
            if ddx * ddx + ddy * ddy <= killr * killr:
                return True
    return False


def _wasm_floor(query, dx, dy, params: HeuristicParams, kernel):
    """Split-aware, WASM-accelerated 1-frame tactical floor — the v9_wasm
    replacement for ``_safe_heading``. Contract is the same: keep the desired
    heading when it is safe, else switch to the best survivable candidate. The
    difference from v8's floor is the threat model (split reach folded in, which
    v8 omitted) and that the fan valuation runs in the embedded kernel (Python
    fallback when WASM is off). Returns a heading ``(dx, dy)``."""
    ours, enemies = _snapshot(query)
    if not ours or not enemies:
        return dx, dy
    if not _rank_threats(ours, enemies, params):
        return dx, dy  # nothing can eat us — no floor needed
    mag = math.hypot(dx, dy)
    bux, buy = (dx / mag, dy / mag) if mag > 1e-9 else (0.0, 0.0)
    # keep the desired heading if it is already death-free (v8 behaviour)
    if mag > 1e-9 and not _heading_lethal(ours, enemies, bux, buy, params):
        return dx, dy
    dirs = _candidate_dirs(dx, dy, params)
    vals = kernel.evaluate(ours, enemies, dirs, bux, buy, params)
    best = max(range(len(dirs)), key=lambda k: vals[k])
    return dirs[best]


class HeuristicController:
    """Phased policy: deterministic greedy FEED early, an optional one-shot VIRUS
    detour, then latch to the potential-field HUNT and never revert. In v9 the
    policy move is refined by a shallow tactical search (:func:`_search_move`)
    before the momentum blend; v9_wasm then applies the WASM-accelerated
    split-aware tactical floor (:func:`_wasm_floor`) in place of ``_safe_heading``.

    FEED (default) forages down the food-density gradient while small. Before
    ``virus_seek_until_round``, the first time we are big enough to eat a virus
    (mass > 2.7) with one in view, we detour to pop it — a +VIRUS_MASS_GAIN bump
    the engine pays out by splitting us to the blob cap (~16 pieces from one
    blob) — but only when ``_virus_pop_safe`` clears it (no enemy can reach the
    pop site by the time we arrive). That pop is the only way a pre-HUNT bot
    gains blobs, so we use ``len(blobs) > 1`` as the "virus eaten" signal and
    hand the scattered pieces straight to HUNT. Otherwise, once the round
    reaches ``feed_until_round`` **and** there is prey our biggest blob can eat
    in view, we commit to HUNT for the rest of the game (``_hunting`` stays
    set). One instance per seat per game — :meth:`reset` returns it to FEED for
    a fresh game; respawns within a game do **not** revert.
    """

    def __init__(self, params: HeuristicParams | None = None) -> None:
        self._params = params or HeuristicParams()
        self._hunting = False
        self._virus_seeking = False
        self._prev_move = (0.0, 0.0)
        self._search_time = 0.0  # cumulative wall-clock spent in the search
        self._kernel = _Kernel()  # instantiate the WASM kernel once (or disable)

    def reset(self) -> None:
        self._hunting = False
        self._virus_seeking = False
        self._prev_move = (0.0, 0.0)
        self._search_time = 0.0
        # keep self._kernel — the module is process-lived, not per-game

    def act(self, query) -> Tuple[float, float, bool]:
        """Phase policy → shallow tactical search → momentum low-pass → 1-frame
        death-zone floor.

        The search (:func:`_search_move`) looks ``search_depth`` frames ahead and
        can override the policy's move — most importantly declining a split that
        the field wants but that loses a blob to an enemy's split reply next
        frame. It runs only when an eater is in play and while the cumulative
        think-time governor allows, and any failure falls back to the policy move
        (so the bot never misses a query). Momentum then damps equilibrium
        jitter (the engine uses only the heading's direction, so we blend on the
        unit vector), and ``_safe_heading`` still runs as a 1-frame floor on
        non-split frames — cheap defense-in-depth beneath the deeper search."""
        dx, dy, split = self._policy(query)
        p = self._params
        if p.search_enabled and self._search_time < p.search_cumulative_cap_s:
            try:
                t0 = time.perf_counter()
                dx, dy, split = _search_move(query, (dx, dy, split), p,
                                             t0 + p.search_time_cap_s)
                self._search_time += time.perf_counter() - t0
            except Exception:
                pass  # on any search failure dx,dy,split keep the policy move
        m = p.momentum
        mag = math.hypot(dx, dy) or 1e-9
        dx, dy = dx / mag, dy / mag
        dx += m * self._prev_move[0]
        dy += m * self._prev_move[1]
        # WASM-accelerated 1-frame floor (split-aware; supersedes _safe_heading).
        # Skipped while splitting: a split-kill is committed and the engine
        # launches the child toward this heading — redirecting it here would
        # scatter the split instead of landing the kill.
        if not split:
            try:
                dx, dy = _wasm_floor(query, dx, dy, self._params, self._kernel)
            except Exception:
                dx, dy = _safe_heading(query, dx, dy, self._params)
        self._prev_move = (dx, dy)
        return dx, dy, split

    def _policy(self, query) -> Tuple[float, float, bool]:
        p = self._params
        if self._hunting:
            return heuristic_action(query, p)

        blobs = query.you.blobs

        # The virus popped us (FEED and the detour never split, so >1 blob can
        # only mean a virus): the detour is done — hand the pieces to HUNT.
        if self._virus_seeking and len(blobs) > 1:
            self._virus_seeking = False
            self._hunting = True
            return heuristic_action(query, p)

        # Detour to the nearest eatable virus while it is early, one is in view,
        # and the pop site is reachability-safe — the pop scatters us to the blob
        # cap into tiny, universally-edible pieces, so never take it (nor keep
        # taking it) when an enemy can reach the pop site in time.
        virus = _nearest_consumable_virus(query)
        safe = virus is not None and _virus_pop_safe(query, virus, p)
        if safe and query.round < p.virus_seek_until_round:
            self._virus_seeking = True
        if self._virus_seeking and safe:
            return virus_seek_action(query, virus, p)
        self._virus_seeking = False  # no reachable/safe virus — resume normal flow

        # normal FEED -> HUNT latch
        if query.round >= p.feed_until_round and _has_eatable_enemy(query):
            self._hunting = True
            return heuristic_action(query, p)
        return greedy_feed_action(query, p)


# --- kit pipe loop + inlined fail-safe (bot never leaves a query unanswered) ---

def _zero_move(player_id: int) -> MovePlayer:
    return MovePlayer(player_id=player_id,
                      direction=DirectionModel(x=0.0, y=0.0), split=False)


def _flee_center(query, player_id: int) -> MovePlayer:
    try:
        x, y = query.you.pos
        dx = spec.ARENA_SIZE / 2.0 - float(x)
        dy = spec.ARENA_SIZE / 2.0 - float(y)
        if abs(dx) > 1e-9 or abs(dy) > 1e-9:
            return MovePlayer(player_id=player_id,
                              direction=DirectionModel(x=dx, y=dy), split=False)
    except Exception:
        pass
    return _zero_move(player_id)


def main() -> None:
    conn = Connection()  # open pipes first — the engine's open-pipe alarm is live
    gc.collect()
    gc.disable()
    controller = HeuristicController()  # FEED->HUNT latch; one game = one process
    player_id = None

    while True:
        try:
            raw = conn._receive()
        except EOFError:
            return
        query = None
        try:
            query = QueryMovePlayer.model_validate_json(raw)
            player_id = query.you.player_id
        except Exception:
            if player_id is None:
                try:
                    player_id = int(json.loads(raw)["you"]["player_id"])
                except Exception:
                    player_id = 0
        try:
            dx, dy, split = controller.act(query)
            move = MovePlayer(player_id=player_id,
                              direction=DirectionModel(x=float(dx), y=float(dy)),
                              split=bool(split))
            if move.player_id != player_id:
                raise ValueError("bad player_id")
        except Exception:
            move = _flee_center(query, player_id) if query is not None \
                else _zero_move(player_id)
        conn.send_move(move)


if __name__ == "__main__":
    main()
